// Reviewed neutral300 only. Synthetic CHS, CTD and PNG headers; no game assets.
static void gfZero(Program& p){p.push(0);p.op(0x300);}
static void gfFilter(Program& p,int id,int mode,int rgb,int contrast,int brightness){p.push(rgb);p.push(mode);p.push(id);p.op(0x253);p.push(contrast);p.push(id);p.op(0x254);p.push(brightness);p.push(id);p.op(0x255);}
static void gfAssertLayer(const std::string& state,int id,int mode,int rgb,int contrast,int brightness,const char* reason){auto layer=layerObject(state,id);check(number(layer,"colorMode")==mode&&number(layer,"rgb")==rgb&&number(layer,"colorValue")==contrast&&number(layer,"brightness")==brightness,reason);}
static void neutralGlobalFilterOnePopNoPushAndImmediate(){
    Program p;for(int value:{11,22,33,44,55})p.push(value);gfZero(p);gfZero(p);gfZero(p);for(int index=0;index<5;++index){p.push(index);p.op(0xe0);}p.dialogue(0);p.op(0xf4);Fixture f(std::move(p));f.command("textSpeed","0");auto state=f.command("action","start");
    check(waiting(state,"input")&&number(state,"nextTickMs")==0&&state.find("\"transition\":null")!=std::string::npos,"repeated300zero continues directly without job/prepare/timer");f.command("save","2");auto saved=mahoyo::save::read(f.root/"savedata/slot2.whs");check(currentHostSchema(saved),"neutral300 requires no new host save schema");InspectHost host;mahoyo::vm::Machine machine(host);machine.loadState(saved.vm);for(int index=0;index<5;++index)check(machine.variable(size_t(index))==(5-index)*11,"300 consumes exactly one top operand and leaves all five sentinels in order");check(machine.stack().empty(),"neutral300 pushes no hidden return value");f.passed=true;
}
static void neutralGlobalFilterPreservesLayersAndPendingEffect(){
    Program p;p.image();gfFilter(p,0,13,0x123456,58,20);effectRequest(p,0,915);gfZero(p);p.dialogue(0);gfFilter(p,0,7,0x0a0b0c,-12,-35);gfZero(p);gfZero(p);p.commit();p.dialogue(1);p.clone(1,0,"fake");gfZero(p);p.dialogue(0);p.op(0xf4);
    const std::string table="915 0 -32767 -32767 -32767 -32767 -32767 -100001 0 0 0 1000\n915 1000 -32767 -32767 -32767 -32767 -32767 -100001 0 0 0 1000\n";
    const std::string windows="915 0 0 0x0 -32767 -32767 -32767 -32767 -32767 -32767\n915 1 1 0x0 -32767 -32767 -32767 -32767 -32767 -32767\n";
    Fixture f(std::move(p),true,table,"fake 100 100\n","",windows);f.command("textSpeed","0");auto state=f.command("action","start");gfAssertLayer(state,0,13,0x123456,58,20,"300zero does not reset existing253 mode/RGB,254contrast or255brightness");
    state=f.command("advance");check(waiting(state,"transitionReady"),"explicit200 after300 alone owns graphics preparation");gfAssertLayer(state,0,7,0x0a0b0c,-12,-35,"300zero preserves new per-layer filter while effect-base edits await prepare");state=acknowledge(f,state);if(waiting(state,"frame"))state=f.command("tick","1000");check(waiting(state,"input"),"neutral300 does not insert an additional wait after common prepare");gfAssertLayer(state,0,7,0x0a0b0c,-12,-35,"prepared scene retains per-layer filter rather than global shader reset");
    f.command("save","2");auto saved=mahoyo::save::read(f.root/"savedata/slot2.whs");check(currentHostSchema(saved),"neutral global default remains portable WH18 state");auto layer=savedLayerFields(saved,0);check(layer[9]=="7"&&std::stoll(layer[11])==0x0a0b0c&&layer[10]=="-12"&&layer[12]=="-35","saved layer retains all four filter fields after repeated300zero");
    std::istringstream input(std::string(saved.hostExtra.begin(),saved.hostExtra.end()));std::string line;size_t count=0;std::getline(input,line);input>>count;std::getline(input,line);for(size_t i=0;i<count;++i)std::getline(input,line);input>>count;std::getline(input,line);check(count==1,"filter fixture retains its active effect");std::getline(input,line);auto effect=hostFields(line);check(effect.size()==35&&effect[20]=="7"&&std::stoll(effect[21])==0x0a0b0c&&effect[24]=="-35"&&effect[25]=="-12"&&effect[34]=="0","WH19 preserves edited pending/effect filter fields and appends explicit decimal");
    auto before=visibleLayers(state);woh_destroy(f.handle);f.handle=woh_create(f.game.string().c_str());f.command("textSpeed","0");state=f.command("load","2");check(visibleLayers(state)==before,"fresh Runtime restores per-layer filters under default-neutral global state");state=f.command("advance");if(waiting(state,"transitionReady"))state=acknowledge(f,state);gfAssertLayer(state,1,7,0x0a0b0c,-12,-35,"terminal clone inherits edited effect-base filter after300zero and fresh load");f.passed=true;
}
static void globalFilterNonNeutralAndEmptyRemainStrict(){
    for(int mode:{-1,1,74,INT32_MIN,INT32_MAX}){Program p(false);p.push(777);p.push(mode);p.op(0x300);p.push(0);p.op(0xe0);p.dialogue(0);p.op(0xf4);Fixture f(std::move(p));auto state=std::string(woh_command(f.handle,"action","start"));check(waiting(state,"error")&&state.find("Unsupported non-neutral global image filter")!=std::string::npos,"non-neutral300 remains unsupported rather than generic global filter/shader implementation");f.passed=true;}
    Program empty(false);empty.op(0x300);empty.op(0xf4);Fixture f(std::move(empty));auto state=std::string(woh_command(f.handle,"action","start"));check(waiting(state,"error")&&state.find("VM peek underflow")!=std::string::npos,"300 requires its one operand and never invents a neutral default");f.passed=true;
}
